import{_ as p,a0 as o,w as d,s as r,I as e,x as n,a1 as l,A as i,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何使用 Ansible 安裝軟件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Ansible 安裝軟件 | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Ansible 安裝軟件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Ansible 安裝軟件 | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20200908 How to install software with Ansible","title":"如何使用 Ansible 安裝軟件","tag":"202010","desc":""},"relativePath":"202010/20200908 How to install software with Ansible.md","filePath":"[post].md"}'),b={name:"202010/20200908 How to install software with Ansible.md"};function c(h,s,g,u,k,m){const a=o("Link");return d(),r("div",null,[s[38]||(s[38]=e("h1",{id:"如何使用-ansible-安裝軟件",tabindex:"-1"},[n("如何使用 Ansible 安裝軟件 "),e("a",{class:"header-anchor",href:"#如何使用-ansible-安裝軟件","aria-label":"Permalink to “如何使用 Ansible 安裝軟件”"},"​")],-1)),s[39]||(s[39]=e("blockquote",null,[e("p",null,"使用 Ansible 劇本自動安裝和更新設備上的軟件。")],-1)),s[40]||(s[40]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202010/10/095024hh65atkh6cc8ntn9.jpg",alt:""})],-1)),e("p",null,[s[2]||(s[2]=n("Ansible 是系統管理員和開發人員用來保持計算機系統處於最佳狀態的一種流行的自動化工具。與可擴展框架一樣，",-1)),l(a,{href:"https://opensource.com/resources/what-ansible"},{default:i(()=>[...s[0]||(s[0]=[n("Ansible",-1)])]),_:1}),s[3]||(s[3]=n(" 本身功能有限，它真正的功能體現在許多模組中。在某種程度上，Ansible 模組就是 ",-1)),l(a,{href:"https://opensource.com/resources/linux"},{default:i(()=>[...s[1]||(s[1]=[n("Linux",-1)])]),_:1}),s[4]||(s[4]=n(" 系統的命令。它們針對特定問題提供解決方案，而維護計算機時的一項常見任務是使所有計算機的更新和一致。",-1))]),s[41]||(s[41]=e("p",null,"我曾經使用軟件包的文本列表來保持系統或多或少的同步：我會列出筆記本電腦上安裝的軟件包，然後將其與台式機或另一台服務器之間進行交叉參考，手動彌補差異。當然，在 Linux 機器上安裝和維護應用程序是 Ansible 的一項基本功能，這意味着你可以在自己關心的計算機上列出所需的內容。",-1)),s[42]||(s[42]=e("h3",{id:"尋找正確的-ansible-模組",tabindex:"-1"},[n("尋找正確的 Ansible 模組 "),e("a",{class:"header-anchor",href:"#尋找正確的-ansible-模組","aria-label":"Permalink to “尋找正確的 Ansible 模組”"},"​")],-1)),e("p",null,[s[6]||(s[6]=n("Ansible 模組的數量非常龐大，如何找到能完成你任務的模組？在 Linux 中，你可以在應用程序菜單或 ",-1)),s[7]||(s[7]=e("code",null,"/usr/bin",-1)),s[8]||(s[8]=n(" 中查找要運行的應用程序。使用 Ansible 時，你可以參考 ",-1)),l(a,{href:"https://docs.ansible.com/ansible/latest/modules/modules_by_category.html"},{default:i(()=>[...s[5]||(s[5]=[n("Ansible 模組索引",-1)])]),_:1}),s[9]||(s[9]=n("。",-1))]),e("p",null,[s[11]||(s[11]=n("這個索引按照類別列出。稍加搜索，你就很可能找到所需的模組。對於包管理，",-1)),l(a,{href:"https://docs.ansible.com/ansible/latest/modules/list_of_packaging_modules.html"},{default:i(()=>[...s[10]||(s[10]=[n("Packaging 模組",-1)])]),_:1}),s[12]||(s[12]=n("幾乎適用於所有帶包管理器的系統。",-1))]),s[43]||(s[43]=t(`<h3 id="動手寫一個-ansible-劇本" tabindex="-1">動手寫一個 Ansible 劇本 <a class="header-anchor" href="#動手寫一個-ansible-劇本" aria-label="Permalink to “動手寫一個 Ansible 劇本”">​</a></h3><p>首先，選擇本地計算機上的包管理器。例如，如果你打算在運行 Fedora 的筆記本電腦上編寫 Ansible 指令（在 Ansible 中稱為“<ruby>劇本<rt>playbook</rt></ruby>”），那麼從 <code>dnf</code> 模組開始。如果你在 Elementary OS 上編寫，使用 <code>apt</code> 模組，以此類推。這樣你就可以開始進行測試和驗證，並可以在以後擴展到其它計算機。</p><p>第一步是創建一個代表你的劇本的目錄。這不是絕對必要的，但這是一個好習慣。Ansible 只需要一個配置文件就可以運行在 YAML 中，但是如果你以後想要擴展劇本，你就可以通過改變目錄和文件的方式來控制 Ansible。現在，只需創建一個名為 <code>install_packages</code> 或類似的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/install_packages</span></span></code></pre></div><p>你可以根據自己的喜好來命名 Ansible 的劇本，但通常將其命名為 <code>site.yml</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch ~/install_packages/site.yml</span></span></code></pre></div><p>在你最喜歡的文本編輯器中打開 <code>site.yml</code>，添加以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- hosts: localhost</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - name: install packages</span></span>
<span class="line"><span>      become: true</span></span>
<span class="line"><span>      become_user: root</span></span>
<span class="line"><span>      dnf:</span></span>
<span class="line"><span>        state: present</span></span>
<span class="line"><span>        name:</span></span>
<span class="line"><span>         - tcsh</span></span>
<span class="line"><span>         - htop</span></span></code></pre></div><p>你必須調整使用的模組名稱以匹配你使用的發行版。在此示例中，我使用 <code>dnf</code> 是因為我在 Fedora Linux 上編寫劇本。</p><p>就像 Linux 終端中的命令一樣，知道 <strong>如何</strong> 來調用 Ansible 模組就已經成功了一半。這個示例劇本遵循標準劇本格式：</p><ul><li><code>hosts</code> 是一台或多台計算機。在本示例中，目標計算機是 <code>localhost</code>，即你當前正在使用的計算機（而不是你希望 Ansible 連接的遠程系統）。</li><li><code>tasks</code> 是你要在主機上執行的任務列表。 <ul><li><code>name</code> 是任務的人性化名稱。在這種情況下，我使用 <code>install packages</code>，因為這就是該任務正在做的事情。</li><li><code>become</code> 允許 Ansible 更改運行此任務的用户。</li><li><code>become_user</code> 允許 Ansible 成為 <code>root</code> 用户來運行此任務。這是必須的，因為只有 root 用户才能使用 <code>dnf</code> 安裝應用程序。</li><li><code>dnf</code> 是模組名稱，你可以在 Ansible 網站上的模組索引中找到。</li></ul></li></ul><p><code>dnf</code> 下的節點是 <code>dnf</code> 模組專用的。這是模組文檔的關鍵所在。就像 Linux 命令的手冊頁一樣，模組文檔會告訴你可用的選項和所需的參數。</p><p><img src="https://opensource.com/sites/default/files/uploads/ansible-module.png" alt="Ansible 文檔" title="Ansible documentation"></p><p>安裝軟件包是一個相對簡單的任務，僅需要兩個元素。<code>state</code> 選項指示 Ansible 檢查系統上是否存在 <strong>軟件包</strong>，而 <code>name</code> 選項列出要查找的軟件包。Ansible 會針對機器的 <strong>狀態</strong> 進行調整，因此模組指令始終意味着更改。假如 Ansible 掃描了系統狀態，發現劇本里描述的系統（在本例中，<code>tcsh</code> 和 <code>htop</code> 存在）與實際狀態存在衝突，那麼 Ansible 的任務是進行必要的更改來使系統與劇本匹配。Ansible 可以通過 <code>dnf</code>（或 <code>apt</code> 或者其它任何包管理器）模組進行更改。</p><p>每個模組可能都有一組不同的選項，所以在編寫劇本時，要經常參考模組文檔。除非你對模組非常熟悉，否則這是期望模組完成工作的唯一合理方法。</p><h3 id="驗證-yaml" tabindex="-1">驗證 YAML <a class="header-anchor" href="#驗證-yaml" aria-label="Permalink to “驗證 YAML”">​</a></h3><p>劇本是用 YAML 編寫的。因為 YAML 遵循嚴格的語法，所以安裝 <code>yamllint</code> 來檢查劇本是很有幫助的。更妙的是，有一個專門針對 Ansible 的檢查工具稱為 <code>ansible-lint</code>，它專門為劇本而生。在繼續之前，安裝它。</p><p>在 Fedora 或 CentOs 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf ins tall yamllint python3-ansible-lint</span></span></code></pre></div><p>在 Debian、Elementary 或 Ubuntu 上，同樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install yamllint ansible-lint</span></span></code></pre></div><p>使用 <code>ansible-link</code> 來驗證你的劇本。如果你無法使用 <code>ansible-lint</code>，你可以使用 <code>yamllint</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ansible-lint ~/install_packages/site.yml</span></span></code></pre></div><p>成功則不返回任何內容，但如果文件中有錯誤，則必須先修復它們，然後再繼續。複製和粘貼過程中的常見錯誤包括在最後一行的末尾省略換行符、使用製表符而不是空格來縮進。在文本編輯器中修復它們，重新運行 <code>ansible-lint</code>，重複這個過程，直到 <code>ansible-lint</code> 或 <code>yamllint</code> 沒有返回為止。</p><h3 id="使用-ansible-安裝一個應用" tabindex="-1">使用 Ansible 安裝一個應用 <a class="header-anchor" href="#使用-ansible-安裝一個應用" aria-label="Permalink to “使用 Ansible 安裝一個應用”">​</a></h3><p>現在你有了一個可驗證的有效劇本，你終於可以在本地計算機上運行它了，因為你碰巧知道該劇本定義的任務需要 root 權限，所以在調用 Ansible 時必須使用 <code>--ask-become-pass</code> 選項，因此係統會提示你輸入管理員密碼。</p><p>開始安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ansible-playbook --ask-become-pass ~/install_packages/site.yml</span></span>
<span class="line"><span>BECOME password:</span></span>
<span class="line"><span>PLAY [localhost] ******************************</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TASK [Gathering Facts] ******************************</span></span>
<span class="line"><span>ok: [localhost]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TASK [install packages] ******************************</span></span>
<span class="line"><span>ok: [localhost]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PLAY RECAP ******************************</span></span>
<span class="line"><span>localhost: ok=0 changed=2 unreachable=0 failed=0 [...]</span></span></code></pre></div><p>這些命令被執行後，目標系統將處於與劇本中描述的相同的狀態。</p><h3 id="在遠程系統上安裝應用程序" tabindex="-1">在遠程系統上安裝應用程序 <a class="header-anchor" href="#在遠程系統上安裝應用程序" aria-label="Permalink to “在遠程系統上安裝應用程序”">​</a></h3><p>通過這麼多操作來替換一個簡單的命令可能會適得其反，但是 Ansible 的優勢是它可以在你的所有系統中實現自動化。你可以使用條件語句使 Ansible 在不同的系統上使用特定的模組，但是現在，假定所有計算機都使用相同的包管理器。</p><p>要連接到遠程系統，你必須在 <code>/etc/ansible/hosts</code> 文件中定義遠程系統，該文件與 Ansible 是一起安裝的，所以它已經存在了，但它可能是空的，除了一些解釋性註釋之外。使用 <code>sudo</code> 在你喜歡的文本編輯器中打開它。</p><p>你可以通過其 IP 地址或主機名（只要主機名可以解析）定義主機。例如，如果你已經在 <code>/etc/hosts</code> 中定義了 <code>liavara</code> 並可以成功 <code>ping</code> 通，那麼你可以在 <code>/etc/ansible/hosts</code> 中將 <code>liavara</code> 設置為主機。或者，如果你正在運行一個域名服務器或 Avahi 服務器並且可以 <code>ping</code> 通 <code>liavara</code>，那麼你就可以在 <code>/etc/ansible/hosts</code> 中定義它。否則，你必須使用它的 IP 地址。</p>`,33)),e("p",null,[s[14]||(s[14]=n("你還必須成功地建立與目標主機的安全 shell（SSH）連接。最簡單的方法是使用 ",-1)),s[15]||(s[15]=e("code",null,"ssh-copy-id",-1)),s[16]||(s[16]=n(" 命令，但是如果你以前從未與主機建立 SSH 連接，",-1)),l(a,{href:"https://opensource.com/article/20/8/how-ssh"},{default:i(()=>[...s[13]||(s[13]=[n("閲讀我關於如何創建自動 SSH 連接的文章",-1)])]),_:1}),s[17]||(s[17]=n("。",-1))]),s[44]||(s[44]=t(`<p>一旦你在 <code>/etc/ansible/hosts</code> 文件中輸入了主機名或 IP 地址後，你就可以在劇本中更改 <code>hosts</code> 定義：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- hosts: all</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - name: install packages</span></span>
<span class="line"><span>      become: true</span></span>
<span class="line"><span>      become_user: root</span></span>
<span class="line"><span>      dnf:</span></span>
<span class="line"><span>        state: present</span></span>
<span class="line"><span>        name:</span></span>
<span class="line"><span>         - tcsh</span></span>
<span class="line"><span>         - htop</span></span></code></pre></div><p>再次運行 <code>ansible-playbook</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ansible-playbook --ask-become-pass ~/install_packages/site.yml</span></span></code></pre></div><p>這次，劇本會在你的遠程系統上運行。</p><p>如果你添加更多主機，則有許多方法可以過濾哪個主機執行哪個任務。例如，你可以創建主機組（服務器的 <code>webserves</code>，台式機的 <code>workstations</code>等）。</p><h3 id="適用於混合環境的-ansible" tabindex="-1">適用於混合環境的 Ansible <a class="header-anchor" href="#適用於混合環境的-ansible" aria-label="Permalink to “適用於混合環境的 Ansible”">​</a></h3><p>到目前為止，我們一直假定 Ansible 配置的所有主機都運行相同的操作系統（都是是使用 <code>dnf</code> 命令進行程序包管理的操作系統）。那麼，如果你要管理不同發行版的主機，例如 Ubuntu（使用 <code>apt</code>）或 Arch（使用 <code>pacman</code>），或者其它的操作系統時，該怎麼辦？</p>`,8)),e("p",null,[s[20]||(s[20]=n("只要目標操作系統具有程序包管理器（",-1)),l(a,{href:"https://opensource.com/article/20/6/homebrew-mac"},{default:i(()=>[...s[18]||(s[18]=[n("MacOs 有 Homebrew",-1)])]),_:1}),s[21]||(s[21]=n("，",-1)),l(a,{href:"https://opensource.com/article/20/3/chocolatey"},{default:i(()=>[...s[19]||(s[19]=[n("Windows 有 Chocolatey",-1)])]),_:1}),s[22]||(s[22]=n("），Ansible 就能派上用場。",-1))]),s[45]||(s[45]=t(`<p>這就是 Ansible 優勢最明顯的地方。在 shell 腳本中，你必須檢查目標主機上有哪些可用的包管理器，即使使用純 Python，也必須檢查操作系統。Ansible 不僅內置了這些功能，而且還具有在劇本中使用命令結果的機制。你可以使用 <code>action</code> 關鍵字來執行由 Ansible 事實收集子系統提供的變量定義的任務，而不是使用 <code>dnf</code> 模組。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- hosts: all</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - name: install packages</span></span>
<span class="line"><span>      become: true</span></span>
<span class="line"><span>      become_user: root</span></span>
<span class="line"><span>      action: &gt;</span></span>
<span class="line"><span>       {{ ansible_pkg_mgr }} name=htop,transmission state=present update_cache=yes</span></span></code></pre></div><p><code>action</code> 關鍵字會加載目標插件。在本例中，它使用了 <code>ansible_pkg_mgr</code> 變量，該變量由 Ansible 在初始 <strong>收集信息</strong> 期間填充。你不需要告訴 Ansible 收集有關其運行操作系統的事實，所以很容易忽略這一點，但是當你運行一個劇本時，你會在默認輸出中看到它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TASK [Gathering Facts] *****************************************</span></span>
<span class="line"><span>ok: [localhost]</span></span></code></pre></div><p><code>action</code> 插件使用來自這個探針的信息，使用相關的包管理器命令填充 <code>ansible_pkg_mgr</code>，以安裝在 <code>name</code> 參數之後列出的程序包。使用 8 行代碼，你可以克服在其它腳本選項中很少允許的複雜跨平台難題。</p><h3 id="使用-ansible" tabindex="-1">使用 Ansible <a class="header-anchor" href="#使用-ansible" aria-label="Permalink to “使用 Ansible”">​</a></h3><p>現在是 21 世紀，我們都希望我們的計算機設備能夠互聯並且相對一致。無論你維護的是兩台還是 200 台計算機，你都不必一次又一次地執行相同的維護任務。使用 Ansible 來同步生活中的計算機設備，看看 Ansible 還能為你做些什麼。</p><hr>`,8)),e("p",null,[s[24]||(s[24]=n("via: ",-1)),l(a,{href:"https://opensource.com/article/20/9/install-packages-ansible"},{default:i(()=>[...s[23]||(s[23]=[n("https://opensource.com/article/20/9/install-packages-ansible",-1)])]),_:1})]),e("p",null,[s[29]||(s[29]=n("作者：",-1)),l(a,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[25]||(s[25]=[n("Seth Kenlon",-1)])]),_:1}),s[30]||(s[30]=n(" 選題：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[26]||(s[26]=[n("lujun9972",-1)])]),_:1}),s[31]||(s[31]=n(" 譯者：",-1)),l(a,{href:"https://github.com/MjSeven"},{default:i(()=>[...s[27]||(s[27]=[n("MjSeven",-1)])]),_:1}),s[32]||(s[32]=n(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[28]||(s[28]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[35]||(s[35]=n("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[33]||(s[33]=[n("LCTT",-1)])]),_:1}),s[36]||(s[36]=n(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:i(()=>[...s[34]||(s[34]=[n("Linux中國",-1)])]),_:1}),s[37]||(s[37]=n(" 榮譽推出",-1))])])}const C=p(b,[["render",c]]);export{y as __pageData,C as default};
